const fetch = require('node-fetch');
const fs = require('fs');
const path = require('path');

// Configuration
const MINT_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const ACTION_URL_BASE = 'https://staging.crossmint.com/api/2022-06-09/actions';
const POLL_INTERVAL_MS = 2000;
const MAX_POLL_ATTEMPTS = 5;
const OUTPUT_PATH = '/home/user/poll_result.json';

