  actionId: 'mock-action-id',
  final_status: 'unknown',
  poll_attempts: 0,
  mint_chain: 'polygon-amoy',
  error: null
};

/**
 * Sleep for specified milliseconds
 */
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Log message to console
 */
function log(message) {
  console.log(`[${new Date().toISOString()}] ${message}`);
}

/**
 * Initiate NFT mint
 */
async function initiateMint() {
  log('Initiating NFT mint...');

  if (!API_KEY) {
    throw new Error('CROSSMINT_API_KEY environment variable not set');
  }

  const response = await fetch(MINT_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY
    },
    body: JSON.stringify({
      recipient: 'email:demo@example.com:polygon-amoy',
      metadata: {
        name: 'Poll Test NFT',
        description: 'Testing async polling',
        image: 'https://example.com/poll.png'
      }
    })
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Mint request failed with status ${response.status}: ${errorText}`);
  }

  const data = await response.json();
  log(`Mint initiated. Response: ${JSON.stringify(data)}`);

  // Extract actionId from response
  const actionId = data.actionId || data.id;
  if (!actionId) {
    throw new Error('No actionId found in mint response');
  }

  result.actionId = actionId;
  return actionId;
}

/**
 * Poll action status
 */
async function pollActionStatus(actionId) {
  const actionUrl = `${ACTION_URL_BASE}/${actionId}`;
  let status = 'pending';
  let attempts = 0;

  log(`Starting to poll action status for actionId: ${actionId}`);

  while (attempts < MAX_POLL_ATTEMPTS && status === 'pending') {
    attempts++;
    result.poll_attempts = attempts;
    log(`Polling attempt ${attempts}/${MAX_POLL_ATTEMPTS}...`);

    try {
      const response = await fetch(actionUrl, {
        method: 'GET',
        headers: {
          'X-API-KEY': API_KEY
        }
      });

      if (!response.ok) {
        const errorText = await response.text();
        log(`Poll request failed with status ${response.status}: ${errorText}`);
        // Continue polling even if one attempt fails
      } else {
        const data = await response.json();
        status = data.status || 'unknown';
        log(`Current status: ${status}`);

        // Update result with latest status
        result.final_status = status;
      }

      // If status is still pending and we haven't reached max attempts, wait before next poll
      if (status === 'pending' && attempts < MAX_POLL_ATTEMPTS) {
        await sleep(POLL_INTERVAL_MS);
      }
    } catch (error) {
      log(`Poll attempt ${attempts} failed: ${error.message}`);
      // Continue polling even if one attempt fails
    }
  }

  log(`Polling completed after ${attempts} attempts. Final status: ${status}`);
  return status;
}

/**
 * Write result to JSON file
 */
function writeResult() {
  try {
    const outputDir = path.dirname(OUTPUT_PATH);

    // Create directory if it doesn't exist
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    fs.writeFileSync(OUTPUT_PATH, JSON.stringify(result, null, 2));
    log(`Result written to ${OUTPUT_PATH}`);
  } catch (error) {
    log(`Failed to write result file: ${error.message}`);
  }
}

/**
 * Main execution
 */
async function main() {
  try {
    log('Starting mint and poll process...');

    // Step 1: Initiate mint
    const actionId = await initiateMint();

    // Step 2: Poll for status
    await pollActionStatus(actionId);

    log('Process completed successfully');
  } catch (error) {
    log(`Error: ${error.message}`);
    result.error = error.message;
  } finally {
    // Step 3: Write result
    writeResult();
  }
}

